def document_plaintext(document: LegalDocument) -> str:
    """Полная редакция для сохранения без ссылок на внешние страницы."""
    blocks = [f"{document.title} — {PROJECT_NAME}", f"Редакция: {DOCUMENT_DATE}"]
    if platega_review_mode():
        blocks.append(REVIEW_PHRASE)
    blocks.extend(f"{heading}\n{text}" for heading, text in document.sections)
    return "\n\n".join(blocks) + "\n"


def _telegram_length(text: str) -> int:
    """Количество единиц UTF-16; символы вне BMP занимают две единицы."""
    return len(text.encode("utf-16-le")) // 2


def _escaped_chunks(text: str, limit: int) -> list[str]:
    """Разбивает длинный текст, не разрывая HTML-сущности и не теряя символы."""
    chunks = []
    remaining = text
    while remaining:
        size = 0
        end = 0
        for character in remaining:
            width = _telegram_length(escape(character))
            if size + width > limit:
                break
            size += width
            end += 1
        if not end:
            raise ValueError("Лимит сообщения слишком мал для текста документа")
        if end < len(remaining):
            boundary = max(remaining.rfind("\n", 0, end), remaining.rfind(" ", 0, end))
            if boundary >= end // 2:
                end = boundary + 1
        chunks.append(escape(remaining[:end]))
        remaining = remaining[end:]
    return chunks


def document_messages(document: LegalDocument, max_length: int = 3800) -> list[str]:
    """Отправляет полную редакцию с номерами частей в пределах лимита Telegram."""
    if not document.sections:
        raise ValueError("Документ должен содержать разделы")
    header = f"<b>{escape(document.title)} — {PROJECT_NAME}</b>\nРедакция: {DOCUMENT_DATE}\n"
    if platega_review_mode():
        header += f"{REVIEW_PHRASE}\n"
    # Число частей заведомо меньше числа символов полной редакции.
    digits = len(str(_telegram_length(document_plaintext(document))))
    counter_reserve = _telegram_length(f"Часть {'9' * digits} из {'9' * digits}\n\n")
    content_limit = max_length - _telegram_length(header) - counter_reserve
    blocks = []
    for heading, text in document.sections:
        section_header = f"<b>{escape(heading)}</b>\n"
        body_limit = content_limit - _telegram_length(section_header) - 2
        if body_limit < 8:
            raise ValueError("Лимит сообщения слишком мал для заголовка документа")
        blocks.extend(section_header + chunk + "\n\n" for chunk in _escaped_chunks(text, body_limit))
    pages = []
    current = ""
    for block in blocks:
        if current and _telegram_length(current) + _telegram_length(block) > content_limit:
            pages.append(current.rstrip())
            current = ""
        current += block
    if current:
        pages.append(current.rstrip())
    total = len(pages)
    return [header + f"Часть {index} из {total}\n\n" + page for index, page in enumerate(pages, 1)]


def public_tariff_rows(tariffs, settings) -> list[dict]:
    """Цены и ограничения из действующих настроек, без выдуманных тарифов."""
    from tgbot.services.device_pricing import slots_cost_for_tariff

    return [{
        "name": tariff.name,
        "price": f"{tariff.price:.2f}",
        "duration_days": tariff.duration_days,
        "base_limit": settings.base_limit,
        "quota": f"{tariff.data_limit_gb} ГБ в месяц" if tariff.data_limit_gb else "Без лимита объема",
        "loyalty_price": f"{tariff.loyalty_price:.2f}" if tariff.loyalty_price else None,
        "price_stars": getattr(tariff, "price_stars", None),
        "extra_price": f"{slots_cost_for_tariff(settings, tariff.duration_days, 1):.2f}",
        "max_extra": settings.max_extra,
    } for tariff in tariffs]
